namespace BlazorApp.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(new[]
        {
            new Notification { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) },
            new Notification { Id = _nextId++, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
            new Notification { Id = _nextId++, Message = "New feature: dark mode is available.", Timestamp = DateTime.UtcNow.AddMinutes(-2) },
        });

        // Simulate new notifications arriving over time.
        _ = GenerateNotificationsAsync();
    }

    public Task<List<Notification>> GetAllAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.OrderByDescending(n => n.Timestamp).ToList());
        }
    }

    public Task<List<Notification>> GetSinceAsync(DateTime since)
    {
        lock (_lock)
        {
            return Task.FromResult(
                _notifications
                    .Where(n => n.Timestamp > since)
                    .OrderByDescending(n => n.Timestamp)
                    .ToList());
        }
    }

    private async Task GenerateNotificationsAsync()
    {
        var messages = new[]
        {
            "Someone liked your post.",
            "You have a new follower.",
            "Server maintenance scheduled.",
            "Your export is ready to download.",
            "New comment on your article.",
            "Weekly digest is available.",
        };

        var rng = new Random();
        while (true)
        {
            await Task.Delay(TimeSpan.FromSeconds(rng.Next(6, 15)));
            lock (_lock)
            {
                _notifications.Add(new Notification
                {
                    Id = _nextId++,
                    Message = messages[rng.Next(messages.Length)],
                    Timestamp = DateTime.UtcNow,
                });
            }
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using BlazorApp.Services
@inject NotificationService NotificationSvc
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (NotificationList is not null)
    {
        <span class="badge">@NotificationList.Count</span>
    }
</h1>

@if (NotificationList is null)
{
    <p><em>Loading notifications…</em></p>
}
else if (NotificationList.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="notification-list">
        @foreach (var n in NotificationList)
        {
            <li>
                <strong>@n.Message</strong>
                <small>@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;
    private DateTime _lastCheck;

    /// <summary>
    /// Persisted across the prerender → interactive boundary so the initial
    /// server-rendered data is reused without a second fetch.
    /// </summary>
    [PersistentState]
    public List<Notification>? NotificationList { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we only fetch when the property wasn't restored from prerender state.
        NotificationList ??= await NotificationSvc.GetAllAsync();
        _lastCheck = NotificationList.Count > 0
            ? NotificationList.Max(n => n.Timestamp)
            : DateTime.UtcNow;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender is never called during prerender — safe to start polling here.
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var newer = await NotificationSvc.GetSinceAsync(_lastCheck);
            if (newer.Count > 0)
            {
                NotificationList!.InsertRange(0, newer);
                _lastCheck = newer.Max(n => n.Timestamp);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

